  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ovotalent.com/learn/glossier-ambassador-program/', 'listing', 'contact', 'OVO Talent''s field guide, citing Glossier''s own contact page (read Oct 26, 2026), lists brand@glossier.com for business and partnership requests.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ovotalent.com/learn/glossier-ambassador-program/', 'listing', 'affiliate', 'Glossier''s Generation Glossier affiliate page (glossier.com/pages/affiliates, formerly on Shopify Collabs) now redirects to the homepage and the footer link is gone, so no public affiliate program is currently offered; Glossier has not said whether it is closed or paused.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ovotalent.com/learn/glossier-ambassador-program/', 'listing', 'ugc_collab', 'Glossier still runs ambassador partnerships and campaigns that it selects itself (including a 2026 influencer-lead job post covering long-term brand ambassadors), but there is no open application and it publishes no creator pay or program terms.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://newcollab.co/brand/glossier', 'listing', 'ugc_collab', 'Newcollab reports Glossier works with UGC creators mainly through product gifting (typical PR package ~$50, no fee) and that @glossier is a verified TikTok account with 1.1M followers; it also states Glossier does not publish UGC rates.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/glossier/', 'affiliate_network', 'compensation', 'Older third-party affiliate listings quote conflicting Glossier commission rates (4% per sale here, 4-10% or up to 10-20% elsewhere), but these describe the former program whose page now redirects, so no current rate could be verified.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 12, 4, 8, 2, 5, '{"compensation": "Glossier publishes no creator pay or current program terms; the only rates found are conflicting third-party figures for a discontinued affiliate program, so this stays at or below 5.", "contact_access": "A partnerships email (brand@glossier.com) is publicly reported from Glossier''s own contact page, but there is no application or partnership page \u2014 mid-range per the rubric.", "credibility": "Established 2014 brand with its own retail stores and wholesale distribution through Sephora, SpaceNK and Mecca.", "niche_fit": "Pure skincare and makeup brand with a cult Gen Z/millennial following \u2014 squarely in the beauty UGC niche.", "opportunity_availability": "No open application exists; the former affiliate page redirects to the homepage and partnerships are initiated by Glossier.", "ugc_evidence": "Brand was built on community UGC and still gifts creators and runs chosen ambassador partnerships, but collaborations are brand-selected with no open program."}'::jsonb);
