  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://brandchamp.io/blog/bubble-ambassador/', 'listing', 'ugc_collab', 'BrandChamp''s guide describes Bubble''s multi-tiered ambassador community (Brand Ambassadors, Campus Ambassadors, Bubble Parents) with applications via the Community section of Bubble''s website and benefits including free products, discounts and the ability to earn commission.', 'publicly_reported', now());
