  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 19, 9, 13, 9, 5, '{"compensation": "Published affiliate data exists \u2014 5% per sale on Impact per the network directory \u2014 and ambassadors can earn commission per BrandChamp, though most ambassador value is product and perks rather than cash fees.", "contact_access": "A public ambassador application route on the official community page, plus a published press email \u2014 top band per the rubric.", "credibility": "Established brand headquartered in New York with national retail distribution at Walmart, Target, CVS and Ulta Beauty.", "niche_fit": "Skincare built specifically for Gen Z and teen creators, with content creation at the center of the brand \u2014 near-perfect UGC niche fit.", "opportunity_availability": "Ambassador and Campus Ambassador applications are publicly open on the official site, including to creators as young as 13 with a public TikTok or Instagram.", "ugc_evidence": "Official site runs a large, structured ambassador community whose content is featured in campaigns and launches, backed by an 85,000+ ambassador network reported by Fashionista."}'::jsonb);
