  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 14, 10, 7, 3, 5, '{"compensation": "Published compensation exists on the brand''s own page ($200 site credit every two months plus full-size launch products), and a third-party directory lists a 7% affiliate commission \u2014 above the no-data cap, though pay is credit/product rather than cash fees.", "contact_access": "A press email for influencer questions (press@glowrecipe.com) is publicly reported from the brand''s contact page, but there is no open application form \u2014 mid-range per the rubric.", "credibility": "Established brand (Aramara Beauty LLC, New York) sold at Sephora and other major retailers, with a verified multi-million-follower social presence.", "niche_fit": "Fruit-forward skincare with a huge TikTok/Instagram following \u2014 a core skincare UGC niche brand.", "opportunity_availability": "The Glow Gang program page is public but states submissions are closed, with only an email subscribe option for reopening news.", "ugc_evidence": "A formal ambassador program with defined monthly creator deliverables on Instagram/TikTok exists on the official site, but it is not currently accepting creators."}'::jsonb);
