  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://summerfridays.com', 'official_site', 'general', 'Summer Fridays'' official homepage sells skincare and hybrid makeup (Jet Lag line, Lip Butter Balm, Dream Lip Oil) and displays ''Follow us @summerfridays'' linking to its Instagram; the brand also posts as @summerfridays on TikTok.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://usesnippet.app/pr-emails/summer-fridays/ambassador-program', 'listing', 'contact', 'Snippet read Summer Fridays'' own pages (checked November 10, 2026) and found no ambassador, affiliate, creator or influencer program published; the route the brand does publish is influencers@summerfridays.com for content creation, influencer and partnership inquiries.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://usesnippet.app/blog/brands-looking-for-ugc-creators', 'listing', 'ugc_collab', 'Snippet''s November 2026 list of brands looking for UGC creators includes Summer Fridays as one of only three skincare brands publishing an email for creators, noting it is an inbox with no application form, so creators need a short pitch.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.glossy.co/beauty/glossy-summit-takeaways-how-summer-fridays-is-staying-ahead-of-the-curve-on-socials/', 'listing', 'ugc_collab', 'In a Glossy interview, co-founder Marianna Hewitt says Summer Fridays works with influencers and talent of all sizes, discovers partners by searching TikTok, and tracks creators through affiliate platforms such as LTK — evidence of active creator collaboration without a public program.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/summer-fridays/', 'affiliate_network', 'compensation', 'Lasso''s directory lists a Summer Fridays affiliate offer of up to 5.25%, but this is uncorroborated and conflicts with Snippet''s November 2026 check finding no affiliate program on the brand''s own pages, so no commission rate could be verified.', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.citybiz.co/article/582241/summer-fridays-announces-strategic-growth-investment-from-tsg-consumer/', 'listing', 'general', 'Business Wire release describes Summer Fridays as a clean, premium skincare and hybrid makeup brand founded in 2018 by Marianna Hewitt and Lauren Ireland and headquartered in Los Angeles, CA.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 12, 4, 8, 2, 5, '{"compensation": "No verified published pay or commission data: the only rate found (Lasso, up to 5.25%) is uncorroborated and contradicted by a check of the brand''s own pages, so this stays at or below 5.", "contact_access": "A dedicated creator/influencer email (influencers@summerfridays.com) is published per a November 2026 check of the brand''s pages \u2014 mid-range per the rubric since there is no application page.", "credibility": "Established 2018 Los Angeles brand, a top-selling skincare brand at Sephora with a strategic growth investment from TSG Consumer Partners.", "niche_fit": "Skincare and hybrid makeup founded by two beauty influencers, with products built for social content \u2014 strong UGC niche fit.", "opportunity_availability": "No public application or program page exists; the only route is pitching the influencer inbox.", "ugc_evidence": "The brand actively works with influencers of all sizes and scouts creators on TikTok per its co-founder, and it appears on a current list of brands seeking UGC creators, but there is no formal public program or application."}'::jsonb);
