  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.gymshark.com/blog/article/fake-gymshark-accounts', 'official_site', 'contact', 'Gymshark''s official blog confirms gymshark.com is the only official store, lists its official social platforms (Instagram, TikTok, Twitter, YouTube, Pinterest, Facebook), and directs questions to its customer support team; it also warns that its Partnerships Teams never DM sponsorship offers.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://marketplace.referly.so/affiliate-programs/gymshark', 'listing', 'affiliate', 'Referly reports the Gymshark affiliate program is run through Partnerize (PHG), pays up to around 4% commission with monthly payouts, and takes applications at join.partnerize.com/gymshark/en; it notes the Gymshark Athlete ambassador program is invitation-only with no application form or direct email.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://en.wikipedia.org/wiki/Gymshark', 'listing', 'general', 'Wikipedia describes Gymshark Ltd as a British athletic apparel retailer headquartered in Solihull, England, founded in 2012, and notes its influencer-led social media marketing.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 16, 8, 9, 5, 5, '{"compensation": "Published third-party data exists: affiliate listings report up to ~4% commission via Partnerize, which is real but low for apparel, so it scores modestly rather than at the no-data cap.", "contact_access": "No public partnerships email or creator application page exists on Gymshark''s own site; access is via the public Partnerize affiliate signup plus a general support contact, which sits in the middle band.", "credibility": "Established global brand founded in 2012 with physical stores, a \u00a31bn+ valuation history and a large real storefront.", "niche_fit": "Fitness is the brand''s entire identity and it was built by fitness creators, so fitness/training creators are a direct audience match.", "opportunity_availability": "The Gymshark66 challenge is a public entry route but is seasonal (pledge window Dec 28-Jan 4) and competitive, and the Athlete program itself has no open application.", "ugc_evidence": "Official blog documents the Gymshark66 UGC challenge as a route to ambassador status and the brand''s marketing is historically creator-led, but the standing Athlete program is scout-based rather than open."}'::jsonb);
