  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 18, 7, 14, 9, 5, '{"compensation": "Published third-party data exists but is weak: roughly 2% affiliate commission is reported, with gifting and perks adding non-cash value; no published UGC rates.", "contact_access": "A public creator application page exists on the brand''s own program domain (community.aerie.com/account/create), which earns the top band.", "credibility": "Established brand of publicly traded American Eagle Outfitters with hundreds of physical stores and a large storefront.", "niche_fit": "Intimates, loungewear, swim and activewear map directly onto fashion, lifestyle and body-positivity creators, Aerie''s core content style.", "opportunity_availability": "The Realmakers application is publicly open year-round, gated only by US base and a 1,500-follower minimum.", "ugc_evidence": "A dedicated creator community (Realmakers) plus the long-running #AerieREAL UGC campaign and social featuring of members give concrete, current creator evidence."}'::jsonb);
