  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 17, 9, 14, 9, 5, '{"compensation": "Published third-party data exists: a 5% affiliate commission is listed and a 5% college-ambassador commission has been reported, but collabs are reported to be mostly gifting with no published UGC rates, so it stays modest.", "contact_access": "A public creator application page (Collab Enquiries) sits on the brand''s official site and is linked from its official support pages, earning the top band.", "credibility": "Established brand owned by NYSE-listed a.k.a. Brands with a global storefront and physical US stores.", "niche_fit": "Trend-driven women''s fashion with daily drops is a direct match for fashion, try-on haul and GRWM creators.", "opportunity_availability": "Collab applications are publicly open with no follower minimum across AU, NZ, US, CA and UK.", "ugc_evidence": "An official collab program, customer featuring on socials/web, and a documented history of micro-influencer collaborations give strong concrete UGC evidence."}'::jsonb);
