  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 12, 12, 4, 3, 5, '{"compensation": "Published third-party data is comparatively strong: affiliate listings report 10% per sale (Lasso) and a 10.5% standard rate via Awin (Uppromote), the highest commission found in this batch.", "contact_access": "No public creator/partnership application page, partnerships email or readable PR email was found on fetched pages, so access is limited to generic site routes and the network signup.", "credibility": "Established global brand founded in 2011 with flagship retail stores, major licensed collaborations and reported ~$300M revenue in 2022.", "niche_fit": "Highly visual, customizable tech accessories are a strong fit for tech, lifestyle and aesthetic creators, though narrower than a pure fashion or fitness brand.", "opportunity_availability": "No public creator/ambassador/UGC application page was found; the only open route is the affiliate network program.", "ugc_evidence": "The brand was built on user Instagram photos, runs artist/brand Co-Labs and promotes a creator community on its homepage, but no public creator program or UGC application evidence was found."}'::jsonb);
