  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://commission.academy/blog/best-grocery-affiliate-programs/', 'listing', 'general', 'Commission Academy describes HelloFresh as a German brand based in Berlin with operations in the US, Australia, Canada and most of Western Europe.', 'publicly_reported', now());
