  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 17, 10, 14, 9, 5, '{"compensation": "Commission is confirmed on the official page and third parties publish flat per-subscriber bounties ($10-$20, conflicting), but HelloFresh itself publishes no rate.", "contact_access": "Public program/application page plus a published program team email (collabs@hellofresh.com).", "credibility": "Global meal-kit leader calling itself America''s #1 meal kit, with a full storefront and long operating history.", "niche_fit": "Meal kits are a proven, high-volume category for food, family and lifestyle creators on Instagram, TikTok and YouTube.", "opportunity_availability": "Ambassador applications are publicly open now (US creators) via the official program page.", "ugc_evidence": "An official, actively promoted Ambassador Program built around creator content, codes and links, with featured-creator opportunities."}'::jsonb);
