  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://studios.traackr.com/register?handle=liquidiv-canada&redirectUrl=https%3A%2F%2Fliquidiv-canada.studios.traackr.com%2F', 'official_site', 'ugc_collab', 'Liquid I.V.''s ambassador sign-up page (Traackr Studios, Canada handle) recruits new Liquid I.V. Ambassadors with product restocks, merch, and eligibility for paid partnerships and event invites in exchange for sharing brand content twice per month.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://usesnippet.app/blog/brands-looking-for-ugc-creators', 'listing', 'affiliate', 'Snippet reports Liquid I.V. runs an affiliate program on GRIN requiring 5,000+ followers on Instagram, TikTok or YouTube, US-based, with a public Instagram, plus an open affiliate program on TikTok Shop; GRIN''s own creator page lists Liquid IV among brands on the platform.', 'publicly_reported', now());
