  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.theatdb.com/companies/liquid-iv', 'listing', 'general', 'ATDb profiles Liquid I.V. as a consumer health and wellness company founded in 2012, headquartered in El Segundo, California, acquired by Unilever in 2020, with growth driven by influencer strategy and user-generated content.', 'publicly_reported', now());
