  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 17, 6, 12, 8, 5, '{"compensation": "No commission or pay rate is published by the brand or GRIN; only a weak aggregator claim of up to 5% exists, so scoring stays low per the rubric.", "contact_access": "A public ambassador application page exists (Traackr Studios sign-up); no partnerships email is published.", "credibility": "Unilever-owned brand founded in 2012 with nationwide retail distribution and a full DTC storefront.", "niche_fit": "Hydration is a staple of wellness, fitness, travel and lifestyle creator content across TikTok and Instagram.", "opportunity_availability": "Ambassador sign-up is publicly open, and the GRIN/TikTok Shop affiliate routes are reported open (GRIN route has a 5,000-follower gate).", "ugc_evidence": "A live ambassador program with paid-partnership eligibility, a GRIN affiliate program, and heavy documented sponsored creator activity on TikTok."}'::jsonb);
